previewCss:
.darma-loader-darma-b14-hydraulic-press { --accent: var(--loader-color, #f59e0b); --accent-2: var(--loader-secondary-color, #475569); width: var(--loader-size, 112px); height: calc(var(--loader-size, 112px) * .88); position: relative; }
.darma-loader-darma-b14-hydraulic-press::before { content: ''; position: absolute; z-index: 3; top: 0; left: 0; width: 100%; height: 13%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #000 18%, var(--accent-2)), color-mix(in srgb, #000 38%, var(--accent-2))); }
.darma-loader-darma-b14-hydraulic-press::after { content: ''; position: absolute; z-index: 3; bottom: 0; left: 0; width: 100%; height: 10%; border-radius: 3px; background: linear-gradient(color-mix(in srgb, #000 38%, var(--accent-2)), color-mix(in srgb, #000 18%, var(--accent-2))); }
.darma-loader-darma-b14-hydraulic-press .darma-loader-darma-b14-hydraulic-press__platen { position: absolute; z-index: 2; left: 15%; width: 70%; height: 13%; border-radius: 2px; background: linear-gradient(var(--accent), color-mix(in srgb, #000 28%, var(--accent))); animation: darma-loader-darma-b14-hydraulic-press-press-down calc(var(--loader-speed, 1s) * 2.6) cubic-bezier(.5, 0, .3, 1) infinite; }
.darma-loader-darma-b14-hydraulic-press .darma-loader-darma-b14-hydraulic-press__platen::after { content: ''; position: absolute; bottom: 100%; left: 44%; width: 12%; height: 340%; background: linear-gradient(90deg, #94a3b8, #e2e8f0, #94a3b8); }
.darma-loader-darma-b14-hydraulic-press span { position: absolute; bottom: 10%; left: 34%; width: 32%; height: 26%; border-radius: 2px; transform-origin: bottom center; background: linear-gradient(var(--accent-2), color-mix(in srgb, #000 26%, var(--accent-2))); animation: darma-loader-darma-b14-hydraulic-press-crush calc(var(--loader-speed, 1s) * 2.6) cubic-bezier(.5, 0, .3, 1) infinite; }
@keyframes darma-loader-darma-b14-hydraulic-press-press-down { 0%, 12% { top: 13%; } 44%, 56% { top: 66%; } 88%, 100% { top: 13%; } }
@keyframes darma-loader-darma-b14-hydraulic-press-crush { 0%, 26% { transform: scale(1, 1); } 46%, 56% { transform: scale(1.28, .42); } 80%, 100% { transform: scale(1, 1); } }

